const runId = process.env.ZEALT_RUN_ID ?? "zr_default";
const normalizedRunId = runId.replace(/-/g, "_");

export const tasksTable = `tasks_${normalizedRunId}`;

import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";
import { tasksTable } from "./tableName";

const schema = defineSchema({
  [tasksTable]: defineTable({
    text: v.string(),
    isCompleted: v.boolean(),
  }),
});

export default schema;

import { v } from "convex/values";
import { mutation, query } from "./_generated/server";
import { tasksTable } from "./tableName";

const tableName = tasksTable as string;

export const list = query({
  args: {},
  handler: async (ctx) => {
    return await ctx.db.query(tableName).order("desc").collect();
  },
});

export const create = mutation({
  args: { text: v.string() },
  handler: async (ctx, args) => {
    const trimmed = args.text.trim();
    if (!trimmed) {
      return null;
    }
    return await ctx.db.insert(tableName, {
      text: trimmed,
      isCompleted: false,
    });
  },
});

export const toggle = mutation({
  args: { id: v.id(tableName as any) },
  handler: async (ctx, args) => {
    const task = await ctx.db.get(args.id);
    if (!task) {
      return null;
    }
    await ctx.db.patch(args.id, { isCompleted: !task.isCompleted });
    return args.id;
  },
});

export const remove = mutation({
  args: { id: v.id(tableName as any) },
  handler: async (ctx, args) => {
    await ctx.db.delete(args.id);
    return args.id;
  },
});

